void subsetsRec(const vector<int>& a, int i, vector<int>& cur,
                vector<vector<int>>& out) {
    if (i == (int)a.size()) { out.push_back(cur); return; }   // leaf: one full decision set
    cur.push_back(a[i]);                 // PICK
    subsetsRec(a, i + 1, cur, out);
    cur.pop_back();                      // undo -- backtracking is a REVERSIBLE edit
    subsetsRec(a, i + 1, cur, out);      // NOT PICK
}

vector<vector<int>> subsets(const vector<int>& a) {
    vector<vector<int>> out; vector<int> cur;
    subsetsRec(a, 0, cur, out);
    return out;
}

// Bitmask variant: mask bit j set means a[j] is in the subset.
vector<vector<int>> subsetsMask(const vector<int>& a) {
    int n = (int)a.size();
    vector<vector<int>> out;
    for (int mask = 0; mask < (1 << n); ++mask) {
        vector<int> cur;
        for (int j = 0; j < n; ++j) if (mask & (1 << j)) cur.push_back(a[j]);
        out.push_back(cur);
    }
    return out;
}

