bool subseqSumExists(const vector<int>& a, int i, long long target) {
    if (target == 0) return true;                 // check BEFORE the index guard
    if (i == (int)a.size()) return false;
    // || short-circuits: if the pick branch succeeds, not-pick is never explored
    return subseqSumExists(a, i + 1, target - a[i]) ||
           subseqSumExists(a, i + 1, target);
}

