    if target == 0:
        return True             # check BEFORE the index guard
    if i == len(a):
        return False
    # 'or' short-circuits: a successful pick branch skips not-pick entirely
    return (subseq_sum_exists(a, target - a[i], i + 1) or
            subseq_sum_exists(a, target, i + 1))

