void combineRec(int n, int k, int start, vector<int>& cur,
                vector<vector<int>>& out) {
    if ((int)cur.size() == k) { out.push_back(cur); return; }
    // PRUNE: need (k - cur.size()) more, only (n - i + 1) remain
    int need = k - (int)cur.size();
    for (int i = start; i <= n - need + 1; ++i) {
        cur.push_back(i);
        combineRec(n, k, i + 1, cur, out);   // i+1: strictly ascending, no reuse
        cur.pop_back();
    }
}

vector<vector<int>> combine(int n, int k) {
    vector<vector<int>> out; vector<int> cur;
    combineRec(n, k, 1, cur, out);
    return out;
}

void combSumRec(const vector<int>& cand, int i, int target,
                vector<int>& cur, vector<vector<int>>& out) {
    if (target == 0) { out.push_back(cur); return; }
    if (i == (int)cand.size() || target < 0) return;
    if (cand[i] <= target) {
        cur.push_back(cand[i]);
        combSumRec(cand, i, target - cand[i], cur, out);   // SAME i = reuse allowed
        cur.pop_back();
    }
    combSumRec(cand, i + 1, target, cur, out);             // move on
}

vector<vector<int>> combinationSum(vector<int> cand, int target) {
    sort(cand.begin(), cand.end());       // optional: makes output tidy and pruning natural
    vector<vector<int>> out; vector<int> cur;
    combSumRec(cand, 0, target, cur, out);
    return out;
}

