def combination_sum(candidates: list, target: int) -> list:
    cand = sorted(candidates)      # optional: tidier output, natural pruning
    out, cur = [], []

    def rec(i, remaining):
        if remaining == 0:
            out.append(cur[:])
            return
        if i == len(cand) or remaining < 0:
            return
        if cand[i] <= remaining:
            cur.append(cand[i])
            rec(i, remaining - cand[i])   # SAME i = reuse allowed
            cur.pop()
        rec(i + 1, remaining)             # move on

    rec(0, target)
    return out

