void phoneRec(const string& digits, int i, string& cur, vector<string>& out) {
    static const vector<string> pad = {"", "", "abc", "def", "ghi",
                                       "jkl", "mno", "pqrs", "tuv", "wxyz"};
    if (i == (int)digits.size()) { out.push_back(cur); return; }
    for (char c : pad[digits[i] - '0']) {
        cur.push_back(c);
        phoneRec(digits, i + 1, cur, out);
        cur.pop_back();
    }
}

