void parenRec(int n, int open, int close, string& cur, vector<string>& out) {
    if ((int)cur.size() == 2 * n) { out.push_back(cur); return; }
    if (open < n) {                    // room for another '('
        cur.push_back('(');
        parenRec(n, open + 1, close, cur, out);
        cur.pop_back();
    }
    if (close < open) {                // only close what is already open
        cur.push_back(')');
        parenRec(n, open, close + 1, cur, out);
        cur.pop_back();
    }
}

vector<string> generateParenthesis(int n) {
    vector<string> out; string cur;
    parenRec(n, 0, 0, cur, out);
    return out;
}

void caseRec(string& s, int i, vector<string>& out) {
    if (i == (int)s.size()) { out.push_back(s); return; }
    if (isalpha((unsigned char)s[i])) {
        s[i] = (char)tolower((unsigned char)s[i]);
        caseRec(s, i + 1, out);
        s[i] = (char)toupper((unsigned char)s[i]);
        caseRec(s, i + 1, out);
        s[i] = (char)tolower((unsigned char)s[i]);   // restore for the caller
    } else {
        caseRec(s, i + 1, out);                       // digits: ONE branch only
    }
}

vector<string> letterCasePermutation(string s) {
    vector<string> out;
    caseRec(s, 0, out);
    return out;
}

