    out, cur = [], list(s)

    def rec(i):
        if i == len(cur):
            out.append("".join(cur))
            return
        if cur[i].isalpha():
            cur[i] = cur[i].lower()
            rec(i + 1)
            cur[i] = cur[i].upper()
            rec(i + 1)
            cur[i] = cur[i].lower()   # restore for the caller
        else:
            rec(i + 1)                # digits: ONE branch only

    rec(0)
