// Assign + or - to every element; can the signed sum reach the target?
bool canReachTarget(const vector<int>& a, int i, long long running, long long target) {
    if (i == (int)a.size()) return running == target;   // every element MUST be signed
    return canReachTarget(a, i + 1, running + a[i], target) ||
           canReachTarget(a, i + 1, running - a[i], target);
}

// Counting variant = LeetCode 494 Target Sum: swap || for +.
long long countWaysToTarget(const vector<int>& a, int i, long long running, long long target) {
    if (i == (int)a.size()) return running == target ? 1 : 0;
    return countWaysToTarget(a, i + 1, running + a[i], target) +
           countWaysToTarget(a, i + 1, running - a[i], target);
}

